css:
/* 'Search' Button theme - */
div.opening-with-search .center-block .search-button{
    text-transform: uppercase;
    font-weight: 700;
    letter-spacing: 1.5px;
    background: transparent;
    border: 2px solid #FFF;
    &:hover {
        background: #FFF;
    }
}
/* END */

/* Header, Add "M" to phone number */
nav#global-navbar .navigation a[href*="tel"] span{
    &:before{
        content: "M: ";
    }
}
/* END */

/* Add 'Learn More' Button */
div.gallery-component__col .gallery-card__title {
    text-align: center;
    font-size: 40px;
    text-transform: none; 
    margin-top: auto;
    margin-bottom: auto;
    padding-bottom: 20px;
    letter-spacing: 3px;

    &:after {
            content: "Learn More";
            position: absolute;
            left: 0;
            right: 0;
            bottom: 0;
            border: 2px solid #fff;
            width: max-content;
            background-color: transparent;
            margin: auto;
            font-family: var(--global-secondary-font-family-short, sans-serif);
            text-transform: uppercase;
            font-size: 14px;
            font-weight: 600;
            line-height: 1.3;
            letter-spacing: 1px;
            padding: 14px 22px;
            transform: translatey(50px)!important;
        }
    &:hover:after{
        background: #FFF;
        color: #162D54;
    }
}
div.gallery-component__col:hover .gallery-card__title:after{
    transform: translatey(60px)!important;
}
a.gallery-card:hover .gallery-card__title:after{
    opacity: 1;

}
a.gallery-card:hover:before {
    background: transparent;
}
.row .gallery-card .gallery-card__preview>img {
    width: 105%!important;
}
div.row.gallery-component__row.cols-3 .gallery-component__col {
    padding: 0px;
    margin-bottom: 0px;
    .gallery-card {
            position: relative;
            width: 100%;
            padding-right: 20px;
            padding-left: 20px;
            height: 385px;
            &:before {
                    background-image: linear-gradient(to bottom, rgba(0, 0, 0, 0) 76.6%, #fff);
                    opacity: 0.6;
                }
                &:before{
                    background-image: linear-gradient(to bottom, rgba(0, 0, 0, 0), rgba(0,0,0,0.95));
                }
        }
}
@media only screen and (max-width: 1024px){
    div.gallery-component__col .gallery-card__title {
    font-size: 28px;
    }
}
@media (max-width: 768px) {
div.row.gallery-component__row.cols-3 .gallery-component__col {
    max-width: 100%;
    flex-basis: 100%;
    padding-right: 0px;
    padding-left: 0px;
            .gallery-card {
                    position: relative;
                    width: 100%;
                    padding-right: 0px;
                    padding-left: 0px;
                    height: 310px;
            }
    }
}
div.gallery-component .lp-container {
    max-width: 100%;
    padding: 0;
}
/* END */

/* Add Headshot/Logo below Social Icons*/
div#modal-global-contact-us .section-details .info-zone {
    &:after {
        content: "";
        display: block;
        width: 100%;
        height: 300px;
        background-image: url(https://res.cloudinary.com/luxuryp/images/f_auto,q_auto/ucnkjthdeigwqculuxgx/tatyana-gavrilyuk);
        background-size: contain;
        background-repeat: no-repeat;
        background-position: 45px 0;
        margin-top: 21px;
        @media (max-width:560px){
            background-position: center;
        }
    }    
}
/* END */

/* Add Headshot/Logo below address */
div#modal-global-contact-us .section-details .info-zone_contact:nth-child(3) {
    &:after {
        content: "";
        display: block;
        width: 100%;
        height: 300px;
        background-image: url(https://res.cloudinary.com/luxuryp/images/f_auto,q_auto/ucnkjthdeigwqculuxgx/tatyana-gavrilyuk);
        background-size: contain;
        background-repeat: no-repeat;
        background-position: 45px 0;
        margin-top: 21px;
        @media (max-width:560px){
            background-position: center;
        }
    }
}
/* END */

/* Add Licenses Number - WB  */

.agent-bio .info .info-block:nth-child(3) {
    display: flex;
    flex-direction: column;
    font-size: 0;
    .info-title {
        font-size: 16px;
        &:after {
            content: 'Washington D.C. - 98377904';
            display: block;
        }
    }
    &:before,
    &:after {
        content: 'Maryland - 664979';
        display: block;
        font-size: 16px;
    }
    &:before{
        order: 1;
    }
    &:after {
        content: 'Virginia - 0225231596';
        order: 2;
    }
}

/* END */

/* Add Logo before title */
.featured-agent-section .container h2.h2{
    &:before {
        content: "";
        display: block;
        width: 100%;
        height: 100px;
        background-image: url(https://res.cloudinary.com/luxuryp/images/w_960,c_limit,f_auto,q_auto/hyez5fpnqeguxlsqm4ap/logo-dark);
        background-size: contain;
        background-repeat: no-repeat;
        margin-bottom: 30px;
    }
}

/* END */

/* Contact Form, Add Logo on Contact Overlay */
@media only screen and (min-width: 769px){
    div#modal-global-contact-us .section-message form{
        &:before{
            content: "";
            background-image: url(https://res.cloudinary.com/luxuryp/images/w_960,c_limit,f_auto,q_auto/uvdxdbzo1vgtmcxliw60/white);
            display: block;
            width: 200px;
            height: 100px;
            -webkit-background-size: contain;
            background-size: contain;
            margin:auto;
            margin-bottom: 0px;
            background-repeat: no-repeat;
        }
    }
}
@media only screen and (max-width: 768px){
    div#modal-global-contact-us .section-details{
        &:before{
            content: "";
            background-image: url(https://res.cloudinary.com/luxuryp/images/w_960,c_limit,f_auto,q_auto/uvdxdbzo1vgtmcxliw60/white);
            display: block;
            width: 200px;
            height: 100px;
            -webkit-background-size: contain;
            background-size: contain;
            margin:auto;
            margin-bottom: 0px;
            background-repeat: no-repeat;
        }
    }
}
/**End**/

/* Contact Form, Add "M" and "O" to phone numbers - */
div#modal-global-contact-us{
    div.section-details .info-zone{
        div:nth-child(1) div:nth-child(2) a{
            &:before{
                content:"M: ";
                display:contents;
            }
        }
        div:nth-child(2) > div > a{
            &:before{
                content:"O: ";
                display:contents;
            }
        }
    }   
}
/* END */

/* Footer, Add "M" to phone number - */
footer#global-footer{
    div.info-wrap .agent_box{
        div:nth-child(1) div:nth-child(3) a{
            &:before{
                content:"M: ";
            }
        }   

        div:nth-child(2) .info-wrap-contact_cell a{
            &:before{
                content:"O: ";
            }
        }
    }   
}
/* END */

/* Add pretitle - */
.center-block .lp-title-group h1.lp-h1:before{
    content: "TOP QUALITY SERVICE & INDUSTRY KNOWLEDGE";
    display: block;
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 18px;
    font-family: var(--global-secondary-font-family);
}
/* END */

div.bottom-container div.info  div:nth-child(4){
    :after{
        content: "3827 Sunset Blvd Los Angeles 90026";
        display: block;
        margin-bottom: 10px;
    }
}

/* Sidemenu, Add Logo at the bottom of the Sidemenu */
div#global-sidemenu{
    .sidebar { 
        position: relative;
        &:before {
        content: "";
        display: block;
        position: absolute;
        width: 100%;
        height: 100%;
        background-image: linear-gradient(rgba(255,255,255, .8),
            rgba(255,255,255, .8)),
            url('');
        background-repeat: no-repeat;
        background-size: contain;
        background-position: bottom;
        bottom: 0;
        }
    }
}
/**End**/

/* Add dark (color) overlay to image */
.press-grid .press-grid__item .press-grid__image{
    position: relative;
    &:after{
        content:"";
        width: 100%;
        height: 100%;
        display: block;
        position: absolute;
        background: linear-gradient(
            to bottom,
            rgba(239,237,242,.0),
            rgba(112,86,124,.6)90%);
    }
}
/* END */

/* Add line color between Testimonials */
.testimonials .data-container .testimonials__item:not(:last-child) {
    border-bottom: 1px solid #B28228;
}
@media (max-width: 768px){
.testimonials .data-container .testimonials__item:not(:last-child) {
    padding-bottom: 30px;
    }
}
/* END */

/* Add logo instead of title */
.center-block h1.lp-h1 {
font-size: 0;
}
.center-block h1.lp-h1:before {
    content: "";
    width: 100%;
    height: 150px;
    display: block;
    filter: invert(1);
    background: url(https://res.cloudinary.com/luxuryp/images/f_auto,q_auto/wobnugwr820sshytavci/signature);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}
/* END */

/* Add logo on hover - */
.gallery-component .gallery-card .gallery-card__preview:after{
        content: "";
        transition: .6s;
        display: block;
        position: absolute;
        z-index: 10;
        width: 100%;
        height: 100%;
        top: 0;
        background: url(https://res.cloudinary.com/luxuryp/images/w_960,c_limit,f_auto,q_auto/hky9mtuixrrclwdzifos/ken-osborn-logo-light);
        background-size: 25%;
        background-repeat: no-repeat;
        background-position: center 85%;
        opacity: 0;
}
.gallery-component .gallery-card:hover{
    .gallery-card__preview:after {
       opacity: 1;
    }
}
/* END */

/* Add padding top&bottom  */
.property-quote{
    padding-top: 96px;
    padding-bottom: 96px;
}
@media (max-width: 768px){
.property-quote{
    padding-top: 64px;
    padding-bottom: 64px;
    }
}
/* END */

/* Header, add scrollbar on dropdown menu - WB */

nav#global-navbar .navigation .sub-nav ul{
    max-height: 300px;
    overflow-y: auto;
    padding: unset;
      &::-webkit-scrollbar {
      width: 5px;
    }

    &::-webkit-scrollbar-track {
        background: rgba(255,255,255,.8);
    }

    &::-webkit-scrollbar-thumb {
      background-color: rgba(0,0,0, .8);
      outline: none;
     }  
}

/* END */

/*Spacing on pagination*/
div.redesign .pagination-container .paginationjs ul li a {
    margin: 0 2px;
}
/*end*/

/* Add two new IDs */
.agent-detail-section ul.contact li:nth-child(2) {
    display: flex;
    flex-direction: column;
    &:before {
        content: "ID 1";
        display: block;
        order: 1;
        margin-top: 6px;
    }
    &:after {
        content: "ID 2";
        display: block;
        order: 2;
        margin-top: 6px;
    }
}
/* END */

/* Footer, add underline to Hyperlinks - */
footer#global-footer .info-wrap-contact a{
    &:before {
        content: "";
        display: block;
        position: absolute;
        bottom: 0;
        width: 100%;
        height: 1px ;
        background-color: currentcolor;
        opacity: .4;
    }
}
/* END */

/* Contact Form, Add underline to links - WB */
div#modal-global-contact-us .container .info-zone_contact a{
      &:before {
            background: #a3a3a3;
            width: 100%;
        }
}
/* END */

/* Adjust 2 press posts per row  */
@media (min-width: 1201px){
    div.press-grid .press-grid__container .press-grid__item{
        width:calc(50% - 30px);
    }
}
/* END */

/* Adjust padding bottom */
@media (min-width: 1230px){
    div.team-grid .lp-container .team-member__container{
        margin-bottom: 0;
    }   
}
@media (min-width: 769px) and (max-width: 1229px){
    div.team-grid .lp-container .team-member__container:nth-last-child(-n+2){
        margin-bottom: 0;
    }   
}
@media (max-width: 768px){
    div.team-grid .lp-container .team-member__container:last-child{
        margin-bottom: 0;
    }   
}
/* END */

/* Adjust 4 agents in a row - */
@media (min-width: 1001px){
    .team-grid .lp-container .team-grid__wrapper{
        .team-member__container {
            flex: 23%;
            width: 23%;
            margin-left: 0;
            margin-right: 0;
            padding: 0 20px;
        }
    }    
}
/* END */

/* Adjust 5 agents in a row  */
@media (min-width: 1001px){
    .team-grid .lp-container .team-grid__wrapper{
        justify-content: center;
        .team-member__container {
            flex: 23%;
            width: 23%;
            max-width: 23%;
            margin-left: 0;
            margin-right: 0;
            padding: 0 20px;
            margin-left: unset!important;
            margin-right: unset!important;
        }
    }    
}
@media (min-width: 1250px){
    .team-grid .lp-container .team-grid__wrapper{
        justify-content: center;
        .team-member__container {
            flex: 19%;
            max-width: 19%;
            margin-left: 0;
            margin-right: 0;
            padding: 0 20px;
        }
        .team-member__hover{
            transform: translate(10px,10px)!important;
        }
        .btn{
            padding: 20px 30px;
        }
    }    
}
/* END */

/* Contact Overlay, Adjust Contact Form to laptop view - WB Leandro rev */
@media (min-width: 1100px) and (max-width: 1440px){
    div#modal-global-contact-us .contact-form{

        padding-top: 50px;
        padding-bottom: 50px;
        .section-message {
            .contact-form {
                margin-bottom: 0!important;
            }
            .form-group_modal{
                margin-bottom: 25px;
            }
        }
    }    
}
/* END */

/* Adjusting Ft. Agent Layout  */
@media (max-width: 1000px) and (min-width: 769px){
    .featured-agent-section .featured-agent {
        flex-direction: column;
    }
    .featured-agent__photo {
        margin-right: 0!important;
        .featured-agent__image{
            text-align: center;
        }    
    }
}

@media (min-width:1001px){
    .featured-agent-section .featured-agent__info {
     padding-top: 0!important;   
    }
}

.featured-agent-section .featured-agent__info .links-row li{
        margin-bottom: 0!important;
}
/* END */

/* Footer, Adjust agent title max-width -  */
@media (min-width: 1200px){
    footer#global-footer .container{
        .info-wrap .serif{
        max-width: 350px;
        }
        .info-wrap-contact {
            padding-left: 300px;
        }
        .text_footer .images_box{
            margin-right: 114px;
        }
    }
}
/* END */

/* Adjust font size number */
div.stats .container .stats__counter {
    font-size: 55px;
}

@media (max-width: 768px){
.stats .container .stats__item {
    padding: 15px 5px!important;
    .stats__counter {
        font-size: 43px!important;
        }
    }   
}
@media (max-width: 320px){
    .stats .container .stats__item {
    padding: 15px 5px!important;
    .stats__counter {
        font-size: 34px!important;
        }
    }   
}
/* END */

/* Adjust image on mobile view */
@media (max-width: 768px){
    .agent-detail-section .lp-container .agent-detail__img{
    background-position: top!important;
    }    
}
/* END */

/* Adjust lines between stats */
div.stats .container .stats__item:after{
    top: 50%;
    transform: translateY(-50%);
    height: 75%;
}
div.stats .container .stats__item:last-child:after{
    content: none;
}
div.stats__container.black-bg{
    justify-content: center;
}
/* END */

/* Footer, Adjust links font-size to avoid overflow -  */
@media (max-width: 385px){
footer#global-footer .footer .info-wrap  a{
        font-size: 12px;
    }
}
/* END */

/* Adjust padding top&bottom */
.stats .container {
    padding-top: 96px;
    padding-bottom: 96px;
}
@media (max-width: 768px){
.stats .container {
    padding-top: 64px;
    padding-bottom: 64px;
    }   
}
/* END */

/* Adjust social icons */
.blog-content .intro-box .socials{
    justify-content: center;
    li {
        padding: 0 7px 10px 7px;
    }
}
/* END */

/* Adjust the Overlapping Line Under the Title - */
div.featured-agent-section .featured-agent__info .h2:after{
    left: 0;
}
/* END */

/*Start - Replace License number - WB Name*/

 .details-list li:nth-child(5) span { 
            visibility: hidden; 
            position: relative; 
        } 
       .details-list li:nth-child(5) span:after { 
            visibility: visible; 
            position: absolute; 
            top: 0; 
            left: 0; 
            content: "S.0168076"; 
        } 

/*END - Replace License number - WB Name*/

/*START - remove excess padding on top and bottom*/
div.redesign .agent-info {
    padding: 96px 0;
}
/*END - remove excess padding on top and bottom*/

/*START - change hyperlink to white*/
div.redesign div.agent-info div.agent-info-details .details-list li a {
    color: #fff!important;
    &:after{
        background-color: #fff;
    }
}
/*START - change hyperlink to white*/

/*START - change hyperlink theme*/
div.bottom-container a.custom-link {
    font-weight:normal;
    color:#e23333!important;
    &:before{
        background-color: #e23333;
    }
    &:after{
        background-color: #2031d1;
    }
    &:hover{
        color:#2031d1!important;
    }
}
/*END- change hyperlink theme*/

/*START - details bar title change to black*/
div.bottom-container{
    div.header,div.info-block{
        color:#000;
    }
}
/*END- details bar title change to black*/

/*start - fix long email address*/
@media only screen and (max-width:1600px){
    div.agent-bio.redesign div.bottom-container div.info{
        div.info-block:nth-child(1){
            width: calc(17% - 30px)!important;
        }
        div.info-block:nth-child(2){
            width: calc(33% - 30px)!important;
        }
    }
}

div.agent-bio.redesign div.bottom-container{
    div.info{
        div.info-block:nth-child(n){
            @media only screen and (max-width:1300px){
                width: calc(50% - 30px)!important;
                margin-bottom: 10px;
            }
            @media only screen and (max-width:768px){
                width: 100%!important;
                a,div.info-title{
                    font-size: 16px;
                }
            }
        }
    }
    @media only screen and (max-width:1300px){
        padding: 25px;
    }
}
/*end - fix long email address*/

/*start - fix very long email address*/
div.agent-bio {
    @media only screen and (max-width: 1068px){
        padding: 50px;
    }
    @media only screen and (max-width: 520px){
        padding: 24px;
    }
}

@media only screen and (max-width:1836px){
    div.agent-bio.redesign div.bottom-container div.info{
        div.info-block:nth-child(1){
            width: calc(17% - 30px)!important;
        }
        div.info-block:nth-child(2){
            width: calc(33% - 30px)!important;
            @media only screen and (max-width:430px){
                a{
                    font-size: 12px;
                }
            }
        }
    }
}

div.agent-bio.redesign div.bottom-container{
    div.info{
        div.info-block:nth-child(n){
            @media only screen and (max-width:1476px){
                width: calc(50% - 30px)!important;
                margin-bottom: 10px;
            }
            @media only screen and (max-width:873px){
                width: 100%!important;
            }
        }
    }
    @media only screen and (max-width:1300px){
        padding: 25px;
    }
}
/*end - fix very long email address*/

/* Footer, Update Agent Name For Logo - */
#global-footer{
    h3{
    font-size: 0;    
        &:before{
          content: "";
          display: block;
          width: 100%;
          height: 200px;
          background-image: url('https://res.cloudinary.com/luxuryp/image/upload/v1622578419/xj2u6r0wyb0wchplvzqv.png');
          background-repeat: no-repeat;
            background-size: contain;
          @media (max-width: 767px){
            height: 200px;
            margin: 0 auto;
            }
        }
    }

}
/* END */

/*START - Change Card Theme Color*/ 
.redesign{ 
    span.label { 
            background: #042D49; 
            color: #fff; 
    } 
    a.agent-properties-item{
        background-color: #c4f1ff;
        .agent-properties-item-text {
            background-color: #c4f1ff;
            p,h4,h5{ 
                color:#000; 
            } 
        }
    }
} 
/*END - Change Card Theme Color*/

/* Agent Title color  */
.team-grid .team-member__container .team-member__role{
    text-transform: uppercase;
    color: #CFA661;
}
/* END */

/* Agent headshot on right side */
@media (min-width: 769px){
.agent-detail-section .lp-container .agent-detail {
    flex-direction: row-reverse;
    }    
}
@media (min-width: 769px) and (max-width: 991px){
    .agent-detail-section .agent-detail .agent-detail__img-wrap{
        padding-left: 30px;
        padding-right: 0!important;
    }
}
@media (min-width: 992px){
   .agent-detail-section .agent-detail .agent-detail__img-wrap{
        padding-left: 130px;
        padding-right: 0!important;
    }
}
/* END */

/* Agents name to ALL Caps */
.team-grid .team-member__container .team-member__name{
    text-transform: uppercase;
}
/* END */

/* Footer, Align Disclaimer Image to the Left - WB */
@media (min-width: 561px){
    footer#global-footer .images_box img{
        object-position: left;
    }       
}
/* END */

/* Header, Align Logo with Homepage opening title */
nav#global-navbar .container {
    width: 83.33333333%;
    max-width: unset;
    padding: 0;
}
/* END */

/* Footer, Align brokerage logo with disclaimer -  */
@media (min-width: 1281px){
footer#global-footer .text_footer .img_size img{
    object-position: top;
    }    
}
/* END */

/* Navbar, Align icon with the Title of "Homepage Opening Element" */
nav#global-navbar .header__container{
    padding: unset!important;
    width: 85%;
}
/* END */

/* Apply underline transition to links - WB */
div.agent-bio .info .info-block a {
    position: relative;
    &:before,
    &:after {
        content: ""; 
        display: block;
        width: 100%;
        height: 1px;
        background-color: #012169;
        opacity: .4;
        position: absolute;
        bottom: 0;
    }

    &:after {
        width: 0;
        opacity: 1;
        transition: width .3s;
    }

    &:hover:after {
        width: 100%;
    }
}
/* END */

/* Avoid ellipsis on content */
div.double-image-grid .cta-section__content .lp-text--subtitle{
    text-overflow: unset;
    white-space: unset;
    -webkit-line-clamp: unset;
}
